export async function createReportPreferencesFixture(){const data=new Map<string,string>();let fail=false;const repo=new Repository({read:async k=>data.get(k)??null,write:async(k,v)=>{if(fail&&k.startsWith('ai-preferences-'))throw Error('模拟保存失败');data.set(k,v);},remove:async k=>{data.delete(k)}});const exp={id:'abcdef123456',name:'测试实验',sourceId:'测试实验',category:'mechanics',schema:{groups:[]}} as unknown as Experiment;const report=new Reports(repo,{context:()=>({exp,doc:{version:1,experimentId:exp.id,date:'2026-10-25',updatedAt:new Date().toISOString(),draft:{}},profile:{name:'',studentId:'',className:''},photo:null,blocked:false}),flush:async()=>{},notice:()=>{},jump:()=>{},configureAI:()=>{},confirm:async()=>true,upload:()=>{}});await report.open();return {state:()=>({saving:report.isSaving,open:report.isOpen,optionWrites:[...data.keys()].filter(k=>k.startsWith('options-')).length}),fail:(v:boolean)=>fail=v,close:()=>report.close(),reopen:()=>report.open(),value:()=>repo.loadAIPreferences(exp.id)};}
